<template>
	<view class="container">
		<custom-nav :title="pageTitle" :isHomePage="false" :scrollTop="scrollTop" ref="customNav" />
		<!-- 内容区域 -->
		<scroll-view scroll-y class="page-container" @scroll="handleScroll" :style="{ 
          paddingTop: navHeight + 'px',
          height: 'calc(100vh - ' + navHeight + 'px)'
        }" :scroll-top="scrollTop" :show-scrollbar="false">
			<view class="doctor-card">
				<view class="doctor-info">
					<view class="name">{{ doctor.name }}</view>
					<view class="detail">
						<text class="location">{{ doctor.location }}</text>
						<text class="gender">{{ doctor.gender }}| &nbsp; </text>
						<text class="age">{{ doctor.age }}</text>
					</view>
					<view class="value">
						<img class="value-icon" src="../../static/images/index/value.png" alt="" />
						{{ doctor.moreInfo.rating }}
					</view>
					<view class="specialty-container">
						<text :class="[
              'doctor-certification',
              doctor.is_certified ? 'certified' : 'uncertified',
            ]">
							{{ doctor.is_certified ? "已认证" : "未认证" }}
						</text>

					</view>
				</view>
				<view class="doctor-avatar">
					<image :src="doctor.avatarUrl" mode="aspectFill"></image>
				</view>
			</view>
			<view class="introduction">
				<!-- <img
        class="introduction-icon"
        src="../../static/images/doctor/user.png"
        alt=""
      /> -->
				<text class="introduction-title">自我介绍</text>
				<view class="introduction-content">
					<text>{{ doctor.moreInfo.self_introduction }}</text>
				</view>
				<view class="work-container">
					<text class="doctor-work">{{ doctor.moreInfo.language }}</text>
					<text class="doctor-work" v-if="doctor.moreInfo.provide_transport">可接送</text>
				</view>
			</view>
			<view class="tech">
				<!--   <img
        class="tech-icon"
        src="../../static/images/index/star (2).png"
        alt=""
      /> -->
				<text class="tech-title">技能证书</text>
				<image :src="doctor.moreInfo.certificate" mode="aspectFill" class="tech-container"></image>
			</view>

			<view class="familiar-hospitals">
				<text class="section-title">熟悉医院</text>
				<view class="hospital-list">
					<view v-for="(hospital, index) in doctor.moreInfo.familiar_hospitals" :key="index"
						class="hospital-item">
						{{ hospital }}
					</view>
				</view>

				<text class="section-title">熟悉科室</text>
				<view class="department-tags">
					<view v-for="(department, index) in doctor.moreInfo.familiar_departments" :key="index"
						class="department-tag">
						{{ department }}
					</view>
				</view>
			</view>
			<view class="appointment">
				<!--  <img
	    class="appointment-icon"
	    src="../../static/images/doctor/hospital.png"
	    alt=""
	  /> -->
				<text class="appointment-title">评价</text>
				<view class="reviews">
					<view class="review-item" v-for="(item, index) in doctor.moreInfo.review" :key="index">
						<view class="review-rating">评分: {{ item.rating }}</view>
						<view class="review-text">{{ item.review }}</view>
					</view>
				</view>
			</view>
		</scroll-view>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				pageTitle: "陪诊师详情",
				scrollTop: 0,
				navHeight: 0, // 存储导航栏高度
				doctor: {}

			};
		},

		/**
		 * 生命周期函数--监听页面加载
		 */
		onLoad(options) {
			const systemInfo = uni.getSystemInfoSync();
			this.navHeight = systemInfo.statusBarHeight + 44;
			if (options.doctor) {
				this.doctor = JSON.parse(decodeURIComponent(options.doctor));
			}
			console.log(this.doctor);
			console.log(this.doctor.moreInfo.certificate);

		},

		/**
		 * 生命周期函数--监听页面初次渲染完成
		 */
		onReady() {},
		/**
		 * 生命周期函数--监听页面显示
		 */
		onShow() {},
		/**
		 * 生命周期函数--监听页面隐藏
		 */
		onHide() {},
		/**
		 * 生命周期函数--监听页面卸载
		 */
		onUnload() {},
		/**
		 * 页面相关事件处理函数--监听用户下拉动作
		 */
		onPullDownRefresh() {},
		/**
		 * 页面上拉触底事件的处理函数
		 */
		onReachBottom() {},
		/**
		 * 用户点击右上角分享
		 */
		onShareAppMessage() {},
		methods: {
			//监视页面滚动情况
			handleScroll(e) {
				if (this.scrollTimer) clearTimeout(this.scrollTimer)
				this.scrollTimer = setTimeout(() => {
					this.scrollTop = e.detail.scrollTop
				}, 16) // 约60fps
			},
		},
	};
</script>

